/**
 * QHSE form config – form codes and API paths aligned with main Oceane-Marine app.
 * Form codes from src/lib/constants/qhse-form-codes.js in main app.
 * Serial numbers are generated by the backend on create (yearwise YYYY-NNN).
 */

export const QHSE_FORM_CONFIG = {
  "audit-form": {
    formCode: "QAF-OFD-055",
    codePath: "qhse/due-diligence/audit-sub-contractor/code",
    createPath: "qhse/due-diligence/audit-sub-contractor/create",
  },
  "hse-induction-checklist": {
    formCode: "QAF-OFD-008",
    codePath: "qhse/form-checklist/hse-induction-checklist/code",
    createPath: "qhse/form-checklist/hse-induction-checklist/create",
  },
  "near-miss": {
    formCode: "QAF-OFD-015",
    codePath: null,
    createPath: "near-miss-form/create",
  },
  "poac-cross-competency": {
    formCode: "QAF-OFD-009",
    codePath: "qhse/cross-competency/code",
    createPath: "qhse/cross-competency/create",
  },
  "supplier-questionnaire": {
    formCode: "QAF-OFD-043",
    codePath: "qhse/due-diligence/due-diligence-questionnaire/code",
    createPath: "qhse/due-diligence/due-diligence-questionnaire/create",
  },
  "transfer-audit-report": {
    formCode: "QAF-OFD-003",
    codePath: "qhse/form-checklist/transfer-audit/code",
    createPath: "qhse/form-checklist/transfer-audit/create",
  },
};

export function getFormConfig(formSlug) {
  return QHSE_FORM_CONFIG[formSlug] || null;
}

export function getFormCodeFallback(formSlug) {
  return QHSE_FORM_CONFIG[formSlug]?.formCode ?? "";
}
